  xfer.msgc = 2;

  t->result = ioctl(t->fd, I2CIOC_TRANSFER, (unsigned long)&xfer);
  t->done = 1;
  return NULL;
}

static int i2c_read_with_timeout(int fd, uint8_t reg, uint8_t *buf, int len)
{
  struct i2c_task task;
  pthread_t tid;
  int wait = 0;

  memset(&task, 0, sizeof(task));
  task.fd   = fd;
  task.reg  = reg;
  task.buf  = buf;
  task.len  = len;
  task.done = 0;
  task.result = -1;

  pthread_create(&tid, NULL, i2c_read_thread, &task);

  while (!task.done && wait < I2C_TIMEOUT_S)
