#define FT6146_ADDR   0x38
#define TIMEOUT_MS    3000

/****************************************************************************
 * Test 1: 通过 /dev/input0 读取触摸事件
 ****************************************************************************/

static int test_touch_device(void)
{
  struct touch_sample_s sample;
  struct pollfd pfd;
  int fd, ret;

  printf("\n--- Test 1: /dev/input0 touch device ---\n");

  fd = open("/dev/input0", O_RDONLY | O_NONBLOCK);
  if (fd < 0)
    {
      printf("[FAIL] open /dev/input0: %d\n", fd);
      return -1;
    }

  printf("[OK] /dev/input0 opened\n");

  /* 读取当前状态 */

  ret = read(fd, &sample, sizeof(sample));
  if (ret < 0)
    {
      printf("[INFO] No pending event (errno=%d), waiting for touch...\n",
             errno);
    }
  else
    {
      printf("[OK] Read: flags=0x%02X x=%ld y=%ld npoints=%ld\n",
             sample.point[0].flags, (long)sample.point[0].x,
             (long)sample.point[0].y, (long)sample.npoints);
    }

  /* 等待触摸事件 */

  printf("[INFO] Please touch screen within %ds...\n", TIMEOUT_MS / 1000);

  pfd.fd     = fd;
  pfd.events = POLLIN;

  ret = poll(&pfd, 1, TIMEOUT_MS);
  if (ret <= 0)
    {
      printf("[FAIL] poll timeout (%dms)\n", TIMEOUT_MS);
      close(fd);
      return -1;
    }

  ret = read(fd, &sample, sizeof(sample));
  if (ret < (int)sizeof(sample))
    {
      printf("[FAIL] read after poll: %d\n", ret);
      close(fd);
      return -1;
    }

  printf("[PASS] Touch event: flags=0x%02X x=%ld y=%ld\n",
         sample.point[0].flags, (long)sample.point[0].x,
         (long)sample.point[0].y);

  close(fd);
  return 0;
}

/****************************************************************************
 * Test 2: 直接 I2C 读取（带超时）
 ****************************************************************************/

static int test_i2c_direct(void)
{
  int fd, ret;
  uint8_t reg = 0xA3;  /* FT6146 ID_H register */
  uint8_t buf[1] = {0};
  struct i2c_msg_s msgs[2];
  struct i2c_transfer_s xfer;

  printf("\n--- Test 2: Direct I2C read at 0x%02X ---\n", FT6146_ADDR);

  fd = open("/dev/i2c0", O_RDWR);
  if (fd < 0)
    {
      printf("[FAIL] open /dev/i2c0: %d\n", fd);
      return -1;
    }

  printf("[OK] /dev/i2c0 opened\n");

  msgs[0].addr   = FT6146_ADDR;
  msgs[0].flags  = 0;
  msgs[0].buffer = &reg;
  msgs[0].length = 1;

  msgs[1].addr   = FT6146_ADDR;
  msgs[1].flags  = I2C_M_READ;
  msgs[1].buffer = buf;
  msgs[1].length = 1;

  xfer.msgv = msgs;
  xfer.msgc = 2;

  printf("[INFO] Reading ID_H (0xA3)...\n");
  ret = ioctl(fd, I2CIOC_TRANSFER, (unsigned long)&xfer);
  if (ret < 0)
    {
      printf("[FAIL] I2C transfer: %d\n", ret);
      close(fd);
      return -1;
    }

  printf("[PASS] ID_H = 0x%02X\n", buf[0]);

  close(fd);
  return 0;
}

/****************************************************************************
 * Test 3: 检查设备节点
 ****************************************************************************/

static void test_device_nodes(void)
{
  printf("\n--- Test 3: Device node check ---\n");

  const char *devs[] =
  {
    "/dev/i2c0", "/dev/i2c1", "/dev/input0",
    "/dev/lcd0", "/dev/fb0", NULL
  };

  for (int i = 0; devs[i]; i++)
    {
      int fd = open(devs[i], O_RDONLY);
      if (fd >= 0)
        {
          printf("[OK] %s exists\n", devs[i]);
          close(fd);
        }
      else
        {
          printf("[FAIL] %s: errno=%d\n", devs[i], errno);
        }
    }
}

/****************************************************************************
 * 主函数
 ****************************************************************************/

int main(int argc, char *argv[])
{
  printf("=== Touch Diagnostic v2 ===\n");

  test_device_nodes();
  test_i2c_direct();
  test_touch_device();

  printf("\n=== Done ===\n");
  return 0;
}

